1	// The library's system of record: one SQLite file, built from world/app/seed by `bun run world`.
2	//
3	// The types below use the database's own column names, such as deposit_cents,
4	// so a row read from SQLite fits them without any renaming.
5	// biome-ignore-all lint/style/useNamingConvention: these names are the database's column names
6	import { Database } from "bun:sqlite";
7	import { appendFileSync, existsSync, mkdirSync, readFileSync, unlinkSync } from "node:fs";
8	import { join } from "node:path";
9	
10	export const WORLD = join(import.meta.dir, "..", "..");
11	export const DATA = join(WORLD, "data");
12	export const DB_PATH = process.env.LIBRARY_DB ?? join(DATA, "library.sqlite");
13	export const EVENTS = join(DATA, "events.jsonl");
14	
15	const SCHEMA = `
16	CREATE TABLE members (
17	  id TEXT PRIMARY KEY,
18	  name TEXT NOT NULL,
19	  phone TEXT NOT NULL,
20	  email TEXT NOT NULL,
21	  joined TEXT NOT NULL,
22	  inductions TEXT NOT NULL
23	);
24	CREATE TABLE items (
25	  id TEXT PRIMARY KEY,
26	  name TEXT NOT NULL,
27	  category TEXT NOT NULL,
28	  safety_class TEXT NOT NULL CHECK (safety_class IN ('A','B','C')),
29	  deposit_cents INTEGER NOT NULL,
30	  status TEXT NOT NULL CHECK (status IN ('in','out','repair'))
31	);
32	CREATE TABLE loans (
33	  id TEXT PRIMARY KEY,
34	  item_id TEXT NOT NULL REFERENCES items(id),
35	  member_id TEXT NOT NULL REFERENCES members(id),
36	  out_date TEXT NOT NULL,
37	  due_date TEXT NOT NULL,
38	  returned_date TEXT
39	);
40	CREATE TABLE reservations (
41	  id TEXT PRIMARY KEY,
42	  item_id TEXT NOT NULL REFERENCES items(id),
43	  member_id TEXT NOT NULL REFERENCES members(id),
44	  from_date TEXT NOT NULL,
45	  to_date TEXT NOT NULL
46	);
47	CREATE TABLE damage_charges (
48	  id TEXT PRIMARY KEY,
49	  loan_id TEXT NOT NULL REFERENCES loans(id),
50	  amount_cents INTEGER NOT NULL,
51	  note TEXT NOT NULL,
52	  split_between TEXT NOT NULL
53	);
54	CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
55	`;
56	
57	export type Member = {
58	  id: string;
59	  name: string;
60	  phone: string;
61	  email: string;
62	  joined: string;
63	  inductions: string[];
64	};
65	export type Item = {
66	  id: string;
67	  name: string;
68	  category: string;
69	  safety_class: "A" | "B" | "C";
70	  deposit_cents: number;
71	  status: "in" | "out" | "repair";
72	};
73	export type Loan = {
74	  id: string;
75	  item_id: string;
76	  member_id: string;
77	  out_date: string;
78	  due_date: string;
79	  returned_date: string | null;
80	};
81	// In the database, split_between is one text of member ids joined by commas.
82	export type DamageCharge = {
83	  id: string;
84	  loan_id: string;
85	  amount_cents: number;
86	  note: string;
87	  split_between: string;
88	};
89	
90	type Row = Record<string, unknown>;
91	
92	function readSeedFile(name: string) {
93	  const path = join(import.meta.dir, "..", "seed", name);
94	  return JSON.parse(readFileSync(path, "utf8"));
95	}
96	
97	// bun:sqlite wants $-prefixed keys for named parameters.
98	function withNamedParameters(row: Row): Row {
99	  const entries = Object.entries(row);
100	  const namedEntries = entries.map(([key, value]) => [`$${key}`, value]);
101	  return Object.fromEntries(namedEntries);
102	}
103	
104	function insertRows(db: Database, sql: string, rows: Row[]) {
105	  const statement = db.prepare(sql);
106	  for (const row of rows) {
107	    statement.run(withNamedParameters(row) as never);
108	  }
109	}
110	
111	// SQLite has no list type, so a list is stored as one text with commas between the parts.
112	function membersForDatabase(members: Member[]): Row[] {
113	  return members.map((member) => ({ ...member, inductions: member.inductions.join(",") }));
114	}
115	
116	function chargesForDatabase(charges: { split_between: string[] }[]): Row[] {
117	  return charges.map((charge) => ({ ...charge, split_between: charge.split_between.join(",") }));
118	}
119	
120	function insertSeed(db: Database) {
121	  const book = readSeedFile("loans.json");
122	  insertRows(
123	    db,
124	    "INSERT INTO items VALUES ($id,$name,$category,$safety_class,$deposit_cents,$status)",
125	    readSeedFile("items.json"),
126	  );
127	  insertRows(
128	    db,
129	    "INSERT INTO members VALUES ($id,$name,$phone,$email,$joined,$inductions)",
130	    membersForDatabase(readSeedFile("members.json")),
131	  );
132	  insertRows(
133	    db,
134	    "INSERT INTO loans VALUES ($id,$item_id,$member_id,$out_date,$due_date,$returned_date)",
135	    book.loans,
136	  );
137	  insertRows(
138	    db,
139	    "INSERT INTO reservations VALUES ($id,$item_id,$member_id,$from_date,$to_date)",
140	    book.reservations,
141	  );
142	  insertRows(
143	    db,
144	    "INSERT INTO damage_charges VALUES ($id,$loan_id,$amount_cents,$note,$split_between)",
145	    chargesForDatabase(book.damage_charges),
146	  );
147	  insertRows(db, "INSERT INTO settings VALUES ($key,$value)", [
148	    { key: "today", value: book.today },
149	    { key: "late_fee_per_day_cents", value: String(book.late_fee_per_day_cents) },
150	  ]);
151	}
152	
153	export function seed(path = DB_PATH): Database {
154	  mkdirSync(DATA, { recursive: true });
155	  if (existsSync(path)) {
156	    unlinkSync(path);
157	  }
158	  const db = new Database(path, { create: true });
159	  db.exec(SCHEMA);
160	  insertSeed(db);
161	  return db;
162	}
163	
164	export function open(path = DB_PATH): Database {
165	  if (!existsSync(path)) {
166	    return seed(path);
167	  }
168	  return new Database(path);
169	}
170	
171	export function setting(db: Database, key: string): string {
172	  const query = db.query("SELECT value FROM settings WHERE key = ?");
173	  const row = query.get(key) as { value: string };
174	  return row.value;
175	}
176	
177	// The inductions column holds text like "B,C"; a member in the app holds a list like ["B", "C"].
178	export const toMember = (row: Row): Member => {
179	  let inductions: string[] = [];
180	  if (row.inductions) {
181	    inductions = String(row.inductions).split(",");
182	  }
183	  return { ...row, inductions } as Member;
184	};
185	
186	// Every desk action is logged, so a check can read what happened without asking anyone.
187	export function logEvent(kind: string, detail: Row) {
188	  mkdirSync(DATA, { recursive: true });
189	  appendFileSync(EVENTS, `${JSON.stringify({ kind, ...detail })}\n`);
190	}
